//! Only product-reviewed compile-time release records can select executable URLs.
use super::*;
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Asset{pub schema_version:u32,pub release_ready:bool,pub engine_revision:String,pub target_os:String,pub target_arch:String,pub bytes:u64,pub sha256:String,pub url:String,pub notices_url:String,pub notices_bytes:u64,pub notices_sha256:String,pub license:String,pub dependencies_reviewed:bool,pub isolation_proven:bool,pub orphan_cleanup_proven:bool}
fn valid_hash(s:&str)->bool{s.len()==64&&s.bytes().all(|c|c.is_ascii_hexdigit()&&!c.is_ascii_uppercase())}
fn https(s:&str)->bool{url::Url::parse(s).is_ok_and(|u|u.scheme()=="https"&&u.host_str().is_some()&&u.username().is_empty()&&u.password().is_none()&&u.fragment().is_none())}
fn valid(a:&Asset)->bool{a.schema_version==1&&a.release_ready&&a.dependencies_reviewed&&a.isolation_proven&&a.orphan_cleanup_proven&&a.engine_revision==ENGINE_REV&&a.target_os==std::env::consts::OS&&a.target_arch==std::env::consts::ARCH&&matches!(a.target_os.as_str(),"linux"|"windows")&&a.license=="MIT"&&a.bytes>0&&a.bytes<=100_000_000&&a.notices_bytes>0&&a.notices_bytes<=2_000_000&&valid_hash(&a.sha256)&&valid_hash(&a.notices_sha256)&&https(&a.url)&&https(&a.notices_url)}
pub fn release()->Option<Asset>{let records:Vec<Asset>=serde_json::from_str(include_str!("voice-releases.json")).ok()?;let mut candidates=records.into_iter().filter(valid);let asset=candidates.next()?;if candidates.next().is_some(){return None}Some(asset)}
fn directory(data:&Path,a:&Asset)->PathBuf{data.join("voice").join("helpers").join(&a.sha256)}
fn executable(a:&Asset)->&'static str{if a.target_os=="windows"{"whisper-cli.exe"}else{"whisper-cli"}}
pub fn lookup(data:&Path)->Result<PathBuf,String>{let asset=release().ok_or("No reviewed optional helper release for this target")?;let root=directory(data,&asset);let meta=fs::symlink_metadata(&root).map_err(|_|"Optional helper not installed")?;if !meta.is_dir()||meta.file_type().is_symlink(){return Err("Invalid helper directory".into())}let path=root.join(executable(&asset));if file_hash(&path)?!=(asset.bytes,asset.sha256.clone())||file_hash(&root.join("THIRD-PARTY-NOTICES.txt"))?!=(asset.notices_bytes,asset.notices_sha256.clone()){return Err("Optional helper checksum mismatch; repair required".into())}Ok(path)}
pub fn present(data:&Path)->bool{release().is_some_and(|a|directory(data,&a).exists())}
pub fn remove(data:&Path)->Result<(),String>{require_preview()?;require_owner()?;let slot=slot().lock().map_err(|_|"Voice busy")?;if slot.as_ref().is_some_and(|j|active(&j.state.phase)){return Err("Voice job active".into())}let a=release().ok_or("No reviewed optional helper release")?;let root=directory(data,&a);if root.exists(){let meta=fs::symlink_metadata(&root).map_err(|_|"Helper unavailable")?;if !meta.is_dir()||meta.file_type().is_symlink(){return Err("Invalid helper directory".into())}fs::remove_dir_all(root).map_err(|_|"Helper removal failed")?;}Ok(())}
#[cfg(feature="desktop")]
pub fn install(data:PathBuf,acknowledged:bool,sha256:String)->Result<String,String>{require_preview()?;let asset=release().ok_or("No reviewed optional helper release")?;if !acknowledged||sha256!=asset.sha256{return Err("Review exact helper size, source, hash and license first".into())}let (id,cancel)=begin("downloading",asset.bytes+asset.notices_bytes)?;let key=id.clone();std::thread::spawn(move||{let result=(||{let runtime=tokio::runtime::Builder::new_current_thread().enable_all().build().map_err(|_|"Helper runtime unavailable")?;runtime.block_on(download(&data,&asset,&key,&cancel))})();match result{Ok(())=>update(&key,if cancel.load(Ordering::SeqCst){"cancelled"}else{"complete"},asset.bytes+asset.notices_bytes,None,None),Err(e)=>update(&key,if cancel.load(Ordering::SeqCst){"cancelled"}else{"failed"},0,None,Some(e))}});Ok(id)}
#[cfg(feature="desktop")]
async fn fetch(url:&str,path:&Path,bytes:u64,sha:&str,id:&str,offset:u64,cancel:&AtomicBool)->Result<(),String>{let host=url::Url::parse(url).map_err(|_|"Invalid helper source")?.host_str().ok_or("Invalid helper host")?.to_owned();let client=reqwest::Client::builder().no_proxy().redirect(reqwest::redirect::Policy::custom(move|attempt|{if attempt.previous().len()>3||attempt.url().scheme()!="https"||attempt.url().host_str()!=Some(host.as_str()){attempt.stop()}else{attempt.follow()}})).connect_timeout(Duration::from_secs(10)).timeout(Duration::from_secs(900)).build().map_err(|_|"Helper download unavailable")?;let mut response=network_step(client.get(url).send(),cancel).await?;if !response.status().is_success(){return Err("Helper source unavailable".into())}let mut file=private_file(path)?;let mut count=0u64;let mut hash=Sha256::new();while let Some(chunk)=network_step(response.chunk(),cancel).await?{count+=chunk.len()as u64;if count>bytes{return Err("Helper download too large".into())}file.write_all(&chunk).map_err(|_|"Helper write failed")?;hash.update(&chunk);update(id,"downloading",offset+count,None,None);}if count!=bytes||format!("{:x}",hash.finalize())!=sha{return Err("Helper checksum mismatch".into())}file.sync_all().map_err(|_|"Helper disk sync failed")?;cancelled(cancel)}
#[cfg(feature="desktop")]
async fn download(data:&Path,a:&Asset,id:&str,cancel:&AtomicBool)->Result<(),String>{let voice=data.join("voice");secure_dir(&voice)?;let base=voice.join("helpers");secure_dir(&base)?;if fs2::available_space(&base).map_err(|_|"Helper volume unavailable")?<a.bytes+a.notices_bytes+64*1024*1024{return Err("Insufficient helper disk space".into())}let stage=base.join(format!("stage-{}",id));secure_dir(&stage)?;let result=(async{let path=stage.join(executable(a));fetch(&a.url,&path,a.bytes,&a.sha256,id,0,cancel).await?;fetch(&a.notices_url,&stage.join("THIRD-PARTY-NOTICES.txt"),a.notices_bytes,&a.notices_sha256,id,a.bytes,cancel).await?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;fs::set_permissions(&path,fs::Permissions::from_mode(0o700)).map_err(|_|"Helper permissions failed")?;}cancelled(cancel)?;let destination=directory(data,a);let backup=base.join(format!("backup-{}",a.sha256));if backup.exists(){return Err("Helper repair recovery required; restart app".into())}if destination.exists(){if fs::symlink_metadata(&destination).map_err(|_|"Helper unavailable")?.file_type().is_symlink(){return Err("Invalid helper directory".into())}fs::rename(&destination,&backup).map_err(|_|"Helper repair staging failed")?;}if fs::rename(&stage,&destination).is_err(){if backup.exists(){let _=fs::rename(&backup,&destination);}return Err("Helper publication failed".into())}if backup.exists(){fs::remove_dir_all(&backup).map_err(|_|"Helper backup cleanup failed")?;}Ok::<(),String>(())}).await;if stage.exists(){let _=fs::remove_dir_all(stage);}result}
#[cfg(test)]mod tests{use super::*;#[test]fn no_invented_release_can_install_or_run(){assert!(release().is_none());let root=tempfile::tempdir().unwrap();assert!(lookup(root.path()).is_err());assert!(!present(root.path()));}#[test]fn urls_and_hashes_fail_closed(){assert!(!https("http://example.invalid/a"));assert!(!https("https://user:pass@example.invalid/a"));assert!(!valid_hash("placeholder"));assert!(!valid_hash(&"A".repeat(64)));}}

pub fn cleanup_staging(data:&Path)->Result<(),String>{let base=data.join("voice").join("helpers");if !base.exists(){return Ok(())}if fs::symlink_metadata(&base).map_err(|_|"Helper cleanup unavailable")?.file_type().is_symlink(){return Err("Invalid helper base".into())}if let Some(a)=release(){let backup=base.join(format!("backup-{}",a.sha256));if backup.exists(){if fs::symlink_metadata(&backup).map_err(|_|"Helper recovery failed")?.file_type().is_symlink(){return Err("Invalid helper backup".into())}let destination=directory(data,&a);if destination.exists(){fs::remove_dir_all(backup).map_err(|_|"Helper recovery cleanup failed")?;}else{fs::rename(backup,destination).map_err(|_|"Helper repair recovery failed")?;}}}for entry in fs::read_dir(&base).map_err(|_|"Helper cleanup unavailable")?{let entry=entry.map_err(|_|"Helper cleanup failed")?;let name=entry.file_name().to_string_lossy().into_owned();if name.starts_with("stage-"){if !entry.file_type().map_err(|_|"Helper cleanup failed")?.is_dir(){return Err("Invalid helper stage".into())}fs::remove_dir_all(entry.path()).map_err(|_|"Helper stage cleanup failed")?;}}Ok(())}
#[cfg(test)]mod release_contract_tests{use super::*;fn fixture()->Asset{Asset{schema_version:1,release_ready:true,engine_revision:ENGINE_REV.into(),target_os:std::env::consts::OS.into(),target_arch:std::env::consts::ARCH.into(),bytes:10,sha256:"a".repeat(64),url:"https://fixture.invalid/not-real-helper".into(),notices_url:"https://fixture.invalid/not-real-notices".into(),notices_bytes:20,notices_sha256:"b".repeat(64),license:"MIT".into(),dependencies_reviewed:true,isolation_proven:true,orphan_cleanup_proven:true}}#[test]fn target_and_release_gates_are_mandatory(){let mut a=fixture();if matches!(std::env::consts::OS,"linux"|"windows"){assert!(valid(&a));}a.isolation_proven=false;assert!(!valid(&a));a=fixture();a.orphan_cleanup_proven=false;assert!(!valid(&a));a=fixture();a.dependencies_reviewed=false;assert!(!valid(&a));a=fixture();a.release_ready=false;assert!(!valid(&a));a=fixture();a.target_arch="wrong".into();assert!(!valid(&a));a=fixture();a.bytes=0;assert!(!valid(&a));a=fixture();a.url="http://fixture.invalid/x".into();assert!(!valid(&a));a=fixture();a.license="GPL".into();assert!(!valid(&a));}}
